// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract Reverter {
    fallback() external payable { revert("nope"); }
    receive() external payable { revert("nope"); }
}

contract InvMutTest is Test {
    SimpleWallet c;
    Reverter r;

    function setUp() public {
        c = new SimpleWallet();
        r = new Reverter();
    }

    function testFuzz_run() public {
        vm.deal(address(c), 1 ether);
        bool reverted;
        try c.sendMoney(address(r), 1, "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}
